window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"-Cza8PzUo7o","speaker":"Lee Jae Myung","role":"President","country":"Republic of Korea","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=-Cza8PzUo7o","date":"20260922","title":"","seconds":916,"words":2019,"counts":{"claims":26,"promises":14,"attacks":0},"topics":[],"timeline":[],"stances":{"UN & its reform":"Lee Jae Myung expresses gratitude to UN member states and staff, congratulates the new UNGA president, and pays tribute to the Secretary-General.","Domestic affairs":"Lee Jae Myung states that the Republic of Korea has announced its 2030 nationally determined contributions and aims to convert its industrial structure through a green transformation strategy to achieve carbon neutrality and create new growth engines.","North Korea":"Lee Jae Myung advocates for cooperation with North Korea based on mutual respect and seeks to establish mechanisms for crisis prevention and peaceful coexistence.","Sustainable Development":"Lee Jae Myung states that the international community must chart a new path forward for the next generation as the 2030 deadline approaches."},"claims":[{"t":137,"quote":"These words of the second secretary general of the UN, Doug Hemershot, compel us to ask ourselves, \"Is the United Nations today capable of saving humanity from war, poverty, and Is the United Nations living up to its promise of restoring peace and achieving sustainable development?\"","topic":"United Nations","kind":"fact"},{"t":163,"quote":"the geopolitical crisis brought on by the turbulence in international order has reminded us of the cherished value of multilateral cooperation and international norms.","topic":"United Nations","kind":"fact"},{"t":203,"quote":"Last year, I proudly announced from this podium that the Republic of Korea, which will be a beacon of life for global citizens, has returned to the international community.","topic":"Republic of Korea culture","kind":"fact"},{"t":231,"quote":"The worldwide popularity of K culture serves as an example demonstrating that universal empathy is possible, showcasing the potential of global","topic":"Republic of Korea culture","kind":"fact"},{"t":290,"quote":"The artificial intelligence revolution is both a massive opportunity and a crisis for humanity.","topic":"Republic of Korea society","kind":"fact"},{"t":296,"quote":"While it can be a core driver of new prosperity and sustainable development, it can it will only deepen inequality and imbalance unless we are properly prepared for it.","topic":"Republic of Korea society","kind":"fact"}],"promises":[{"t":265,"quote":"The Republic of Korea will build on the power of empathy and solidarity that culture has brought to light.","topic":"Republic of Korea culture","kind":"promise"},{"t":272,"quote":"We will harness that power to address the common challenges facing all of humanity.","topic":"Republic of Korea society","kind":"promise"},{"t":328,"quote":"The Republic of Korea is pursuing an AI transformation that will ensure stronger protection of human fundamental rights across fields such as social security, labor, housing, and culture.","topic":"Republic of Korea society","kind":"promise"},{"t":392,"quote":"We will take the lead in shaping AI into a tool for solving the shared challenges we face such as the climate crisis, public health, food insecurity and refugee issues.","topic":"Republic of Korea health","kind":"promise"},{"t":452,"quote":"We are ready to share our experience and best practices with the international","topic":"Republic of Korea environment","kind":"promise"},{"t":654,"quote":"The Republic of Korea will live up to its responsibility and position to deliver results that can be vividly felt by people around the world across the UN's three pillars of peace, development, and human rights.","topic":"United Nations","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[],"compare":[{"topic":"North Korea","share":0.3461,"mean":0.0017,"rank":1,"others":4},{"topic":"UN & its reform","share":0.2908,"mean":0.2043,"rank":50,"others":170},{"topic":"Sustainable Development","share":0.0687,"mean":0.0122,"rank":13,"others":28}]};
